N_range = range(1, 11)

for m in M_range:
    for n in N_range:
        for p in P_values:
            # Check condition 1: m^2 + n is a power of p >= p^2
            val1 = m*m + n
            is_power1 = False
            exponent1 = 0
            if val1 > 0:
                # Check if val1 is a power of p
                temp = val1
                if temp == 1:
                    # 1 is p^0, but we need a >= 2.
                    pass
                else:
                    while temp > 0 and temp % p == 0:
                        temp //= p
                        exponent1 += 1

                    if temp == 1 and exponent1 >= 2:
                        is_power1 = True

            # Check condition 2: m + n^2 is a power of p >= p^2
            val2 = m + n*n
            is_power2 = False
            exponent2 = 0
            if val2 > 0:
                # Check if val2 is a power of p
                temp = val2
                if temp == 1:
                    pass
                else:
                    while temp > 0 and temp % p == 0:
                        temp //= p
                        exponent2 += 1

                    if temp == 1 and exponent2 >= 2:
                        is_power2 = True

            if is_power1 and is_power2:
                solutions.append((m, n, p))

print("Found solutions (m, n, p):")
