def check_solution(m, n, p):
    if m <= 0 or n <= 0 or not isinstance(p, int) or p <= 1:
        return False
    if not is_prime(p):
        return False

    # Check conditions
    try:
        val1 = m**2 + n
        val2 = m + n**2
    except OverflowError:
        return False # Too large for integer check

    # Check log_p(m^2+n) > 1 and integer
    if val1 <= 1: return False
    if val1 % p != 0: # Simplistic check, requires exact power
        log1 = None
    else:
        # Check if val1 is a power of p
        temp1 = val1
        log1 = 0
        while temp1 > 1 and temp1 % p == 0:
            temp1 //= p
            log1 += 1
        if temp1 != 1:
            log1 = None # Not a power of p

    if log1 is None or log1 <= 1:
        return False

    # Check log_p(m+n^2) > 1 and integer
    if val2 <= 1: return False
    if val2 % p != 0:
        log2 = None
    else:
        # Check if val2 is a power of p
